@push('head')
<style>
.ai-wrap{max-width:1160px;margin:auto;padding:54px 24px 80px}.ai-hero{padding:34px 0 54px;display:grid;grid-template-columns:1.3fr 1fr;gap:44px;align-items:center}.ai-hero h1{font-size:clamp(32px,5vw,58px);line-height:1.35;letter-spacing:-1px;margin:18px 0}.ai-lead{font-size:18px;line-height:1.95;color:#adb9cb}.ai-label{color:#82cfff;font-size:13px;letter-spacing:1px}.ai-actions{display:flex;gap:12px;flex-wrap:wrap;margin:26px 0}.ai-btn{display:inline-flex;align-items:center;padding:12px 20px;border:1px solid #3b536c;border-radius:12px;color:#e5f0ff;text-decoration:none}.ai-btn.primary{background:#80ceff;color:#092036;border-color:#80ceff;font-weight:700}.ai-code{direction:ltr;text-align:left;overflow:auto;background:#0b1524;border:1px solid #29425a;border-radius:18px;padding:24px;font:13px/1.9 ui-monospace,monospace;white-space:pre;box-shadow:0 18px 70px #07355033;max-width:100%}.ai-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.ai-card{border:1px solid #293a51;background:#101c2c;border-radius:16px;padding:22px;min-width:0}.ai-card h2,.ai-card h3{font-size:19px;line-height:1.5;margin:10px 0;overflow-wrap:anywhere}.ai-card p{color:#aebed0;line-height:1.85}.ai-pill{display:inline-block;border-radius:20px;padding:4px 10px;font-size:12px;background:#25344b;color:#bacbdd}.ai-pill.ready{color:#88e2bd;background:#163d35}.ai-section{margin:44px 0}.ai-section h2{font-size:28px;margin-bottom:20px}.ai-price{display:flex;gap:26px;margin:18px 0}.ai-price strong{display:block;font-size:23px;margin-top:8px}.ai-muted{color:#aebed0;line-height:1.9}.ai-note{border-inline-start:3px solid #80ceff;padding:8px 18px;background:#122538;border-radius:5px;line-height:1.95;color:#bed2e8;margin:24px 0}.ai-search{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.ai-search input,.ai-search select{padding:12px;border-radius:9px;border:1px solid #3b536c;background:#101c2c;color:#e4eefb;min-width:160px}.ai-search input{flex:1}.ai-faq details{padding:20px 0;border-bottom:1px solid #2a3b50}.ai-faq summary{cursor:pointer;font-weight:700;line-height:1.8}.ai-spec{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.ai-spec dd{font-size:22px;margin:10px 0}.ai-steps{line-height:2.2;padding-inline-start:24px}.ai-table{width:100%;border-collapse:collapse;font-size:13px}.ai-table th,.ai-table td{text-align:start;border-bottom:1px solid #293a51;padding:12px;white-space:nowrap}.ai-nav{display:flex;gap:20px;flex-wrap:wrap;padding:0 0 24px}.ai-nav a{color:#a9d9fb}.ai-pagination{margin:30px 0}.ai-pagination svg{width:20px;height:20px}.ai-pagination nav{display:block}
@media(max-width:760px){.ai-hero{grid-template-columns:1fr;gap:10px}.ai-grid{grid-template-columns:1fr}.ai-wrap{padding:28px 18px 52px}.ai-code{padding:16px;font-size:11px}.ai-section h2{font-size:24px}.ai-actions .ai-btn{flex:1;justify-content:center}.ai-spec{grid-template-columns:1fr 1fr}}
</style>
<style>
.ai-table-scroll{max-width:100%;overflow:auto;border:1px solid #293a51;border-radius:12px}.ai-table-scroll:focus-visible{outline:2px solid #80ceff}.ai-table-scroll .ai-table td:last-child{white-space:normal;min-width:220px;line-height:1.8}.ai-table code{font-size:12px}
.ai-model-title{font-size:clamp(28px,4vw,46px);line-height:1.45;overflow-wrap:anywhere}.ai-breadcrumb{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:24px;font-size:13px;color:#aebed0}.ai-breadcrumb a{color:#a9d9fb}.ai-facts .ai-spec{grid-template-columns:1fr}.ai-facts .ai-spec dd{font-size:15px;overflow-wrap:anywhere;margin:6px 0}.ai-facts .ai-spec dt{font-size:12px;color:#aebed0}.ai-steps{color:#c6d3e3}.ai-section>h2:not(:first-child){margin-top:32px}.ai-faq details p{max-width:86ch}
.ai-facts .ai-spec{grid-template-columns:repeat(2,minmax(0,1fr))}.ai-facts .ai-spec>div:first-child{grid-column:1/-1}.ai-wrap .ai-lead,.ai-wrap .ai-muted,.ai-wrap .ai-section p{max-width:90ch}
html[data-theme="light"] .ai-card,html[data-theme="light"] .ai-search input,html[data-theme="light"] .ai-search select{background:var(--surface);border-color:var(--line-2);color:var(--text)}html[data-theme="light"] .ai-muted,html[data-theme="light"] .ai-lead,html[data-theme="light"] .ai-card p,html[data-theme="light"] .ai-steps,html[data-theme="light"] .ai-facts dt,html[data-theme="light"] .ai-breadcrumb{color:var(--muted)}html[data-theme="light"] .ai-nav a,html[data-theme="light"] .ai-label,html[data-theme="light"] .ai-breadcrumb a{color:#155d91}html[data-theme="light"] .ai-note{background:#e7f3fc;color:#244661}html[data-theme="light"] .ai-btn:not(.primary){color:var(--text);border-color:var(--line-2)}html[data-theme="light"] .ai-table td,html[data-theme="light"] .ai-table th,html[data-theme="light"] .ai-faq details,html[data-theme="light"] .ai-table-scroll{border-color:var(--line-2)}
</style>

@endpush
